#!/usr/bin/env -S uv run --script
# Synced from bootstrap: macos/tools/mise/tasks/upgrade-macos-download.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Download macOS updates"
# MISE hide=true
# MISE dir="~"
# MISE tools={uv="latest", python="3.14"}

import os
import shutil
import subprocess
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, os.path.expanduser("~/.config/mise/tasks/_scripts"))
import helpers  # noqa: E402


def run(*cmd):
  """Run the command. When it fails, stop the task with its code."""
  rc = subprocess.run(cmd, check=False).returncode
  if rc:
    sys.exit(128 - rc if rc < 0 else rc)


def main():
  helpers.print_header("Installing Rosetta 2 ...")
  run("softwareupdate", "--install-rosetta", "--agree-to-license")

  helpers.print_header("Downloading macOS updates ...")
  run("softwareupdate", "--download", "--all")

  helpers.print_header("Upgrades from AppStore ...")
  if shutil.which("mas"):
    run("mas", "upgrade")
  else:
    helpers.print_warn("Skipping mas upgrade: mas is not on PATH (its tool is not selected)")


if __name__ == "__main__":
  main()
